"""Build a source-labelled, offline comparison of all current and Claude candidate audio."""
from pathlib import Path
import base64,json,html
R=Path(__file__).resolve().parents[2];D=R/'docs/audio-reference-review';inv=json.loads((D/'inventory.json').read_text());assess={r['asset']:r for r in json.loads((D/'assessment.json').read_text())};candidates=json.loads((D/'candidate-previews.json').read_text());mix=json.loads((D/'mix-demos.json').read_text());cards=[]
def e(s):return html.escape(str(s))
def audio(path):
 p=R/path;return '<audio controls preload="none" src="data:audio/'+('ogg' if p.suffix=='.ogg' else 'mpeg')+';base64,'+base64.b64encode(p.read_bytes()).decode()+'"></audio>'
for r in inv['assets']:
 a=assess[r['asset']];group='music' if r['kind']=='music' else 'sfx';cards.append('<article data-kind="'+group+'" data-asset="'+e(r['asset'])+'"><span class="badge">'+e(a['priority']+' · '+a['proposal'])+'</span><h3>'+e(a['role'])+'</h3><code>'+e(r['asset'])+'</code><p class="meta">'+e(r['sourceStatus'])+' · '+str(r['duration'])+'秒</p>'+audio(r['path'])+'<p>'+e(a['reason'])+'</p><label>我的意見 <select class="decision"><option value="not-reviewed">尚未試聽</option value="keep">保留</option><option value="revise">修改</option><option value="replace">替換</option></select></label><button class="pick" data-slot="A">放入 A</button><button class="pick" data-slot="B">放入 B</button></article>')
for r in candidates:
 cards.append('<article data-kind="online" data-asset="'+e(r['id'])+'"><span class="badge">線上候選 · CC0 · 未接入遊戲</span><h3>'+e(r['title'])+'</h3><p class="meta">'+e(r['author'])+' · '+('前30秒、匹配響度的比較片段' if 'excerptSeconds' in r else '原包完整單一音效')+'</p>'+audio(r['path'])+'<p>'+e(r['processing'])+'</p><a href="'+e(r['page'])+'" target="_blank" rel="noopener">完整來源／授權</a><label>我的意見 <select class="decision"><option value="not-reviewed">尚未試聽</option><option value="candidate">保留候選</option><option value="reject">不採用</option></select></label><button class="pick" data-slot="A">放入 A</button><button class="pick" data-slot="B">放入 B</button></article>')
demos=''.join('<article><h3>'+e(r['id'])+' · 同一組事件的16秒示意</h3>'+audio(r['file'])+'</article>' for r in mix['demos'])
page='''<!doctype html><html lang="zh-Hant"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Hello, Static! 全音訊審查</title><style>*{box-sizing:border-box}body{margin:0;background:#e7ebf4;color:#243854;font:16px/1.65 system-ui}header,main{max-width:1300px;margin:auto;padding:18px}h1{font-size:28px;line-height:1.3}h2{font-size:23px}h3{font-size:18px;margin:8px 0}p{margin:8px 0}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,320px),1fr));gap:14px}article{min-width:0;background:#fafbff;border:1px solid #99a8c6;box-shadow:3px 3px #c8d0e1;padding:16px}article[hidden]{display:none}audio{width:100%;margin:12px 0}button,select,input{font:inherit;min-height:44px;max-width:100%;padding:6px 10px;margin:4px 6px 4px 0;background:white;border:1px solid #798dad;border-radius:3px;color:inherit}a{color:#274d94;overflow-wrap:anywhere}code,.meta{font-size:13px;overflow-wrap:anywhere}.badge{font-size:12px;padding:3px 6px;background:#dce3fa}label{display:block}.toolbar{background:#d9e0f5;padding:12px;border:1px solid #99a8c6}.toolbar b{display:block}.warning{border-left:4px solid #7b6cb5;padding-left:12px}.refs a{display:inline-block;padding:4px 12px 4px 0}#search{width:300px}#count{font-size:14px}</style>
<header><h1>Hello, Static! 全音訊審查</h1><p>6首配樂＋46個基礎音效：正式來源3add8a6，另標示Claude8ee3a2e待發素材。線上候選4首配樂與6個音效均另列，不是已替換的正式版本。</p><p class="warning">此處完成來源、用途、數值與設計審查；未冒稱已親耳完成全部素材聽感驗收。兩段YouTube未能直接播放：Dream Logic身分／描述由使用者提供，Dorephin的短鋼琴編排有官方製作說明。線上候選依授權及曲目描述入圍，最終貼合度仍需試聽。</p><p class="refs"><a href="https://www.youtube.com/watch?v=Gbu3iBi9F7Y" target="_blank" rel="noopener">Into Moon · Dream Logic</a><a href="https://www.youtube.com/watch?v=gvtrG92q32Q" target="_blank" rel="noopener">Dorephin Shopping Center</a><a href="https://azikazinmagicworld.com/en/news/5299/" target="_blank" rel="noopener">Dorephin官方製作說明</a></p><p>聲音素材單聽不等同遊戲混音。線上音樂只是前30秒比較片段，不是製作好的無縫loop；音效原檔未正規化。未試聽的項目不會自動填通過，選擇只留本頁記憶體。</p><div class="toolbar"><button id="stop">全部停止</button><button id="export">下載意見 JSON</button><label>試聽音量 <input id="volume" type="range" min="0" max="0.8" step="0.05" value="0.45"></label><b id="A">A：尚未選擇</b><b id="B">B：尚未選擇</b><button id="playA">播放 A</button><button id="playB">播放 B</button><span id="status" role="status"></span></div></header><main><h2>同事件 A／B 示意</h2><p>A用現有drift；B用Wednesday Night候選及兩種外部音效。事件時間相同，並非遊戲引擎錄音；此例只比較一個方向，不表示選定整套。</p><section class="grid">'''+demos+'''</section><h2>逐項審查與線上候選</h2><label>篩選 <select id="filter"><option value="all">全部62項</option><option value="music">配樂6首</option><option value="sfx">音效46項</option><option value="online">線上候選10項</option></select></label><input id="search" type="search" placeholder="搜尋用途、檔名或建議" aria-label="搜尋"><p id="count"></p><section id="items" class="grid">'''+''.join(cards)+'''</section><p>第三方來源：iamoneabe、Zane Little Music、The Cynic Project／cynicmusic.com／pixelsphere.org、Kenney。CC0來源與處理記錄另見交付包。兩首YouTube參考沒有遊戲嵌入授權紀錄，未擷取其錄音或借用旋律。Ice Cream.mp4仍為街頭日常與視覺節奏的最高參考。</p></main><script>
const all=[...document.querySelectorAll('audio')],cards=[...document.querySelectorAll('#items article')],slots={A:null,B:null};for(const a of all){a.volume=.45;a.addEventListener('play',()=>all.forEach(b=>{if(a!==b)b.pause()}));}document.getElementById('stop').onclick=()=>{all.forEach(a=>{a.pause();a.currentTime=0});document.getElementById('status').textContent=''};document.getElementById('volume').oninput=e=>all.forEach(a=>a.volume=+e.target.value);document.querySelectorAll('.pick').forEach(b=>b.onclick=()=>{const c=b.closest('article'),s=b.dataset.slot;slots[s]=c.querySelector('audio');document.getElementById(s).textContent=s+'：'+c.dataset.asset;});for(const s of ['A','B'])document.getElementById('play'+s).onclick=()=>{if(slots[s])slots[s].play().then(()=>document.getElementById('status').textContent='').catch(e=>{if(e.name!=='AbortError')document.getElementById('status').textContent='請再次點擊播放'});else document.getElementById('status').textContent='先把一項放入 '+s;};function filter(){let n=0;const kind=document.getElementById('filter').value,q=document.getElementById('search').value.toLowerCase();cards.forEach(c=>{c.hidden=!(kind==='all'||c.dataset.kind===kind)||!c.textContent.toLowerCase().includes(q);if(!c.hidden)n++});document.getElementById('count').textContent=n+'項';}document.getElementById('filter').onchange=filter;document.getElementById('search').oninput=filter;filter();document.getElementById('export').onclick=()=>{const value={mainSource:'3add8a6',claudeSource:'8ee3a2e',scope:'Human choices; no production changes',items:cards.map(c=>({asset:c.dataset.asset,choice:c.querySelector('.decision').value}))},url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download='audio-review-decisions.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
</script></html>'''
(R/'dist/audio-reference-review.html').write_text(page);print('built',len(cards),'review cards',len(page.encode()),'bytes')
